<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import type { CatalogoNumeracion, NumeracionTipoComprobante, NumeracionTipoComprobantePayload } from '../interfaces/numeracion-tipo-comprobante.interface'
import { cambiarEstadoNumeracionTipoComprobante, guardarNumeracionTipoComprobante, listarNumeracionesTipoComprobante, obtenerNumeracionTipoComprobante } from '../services/numeracion-tipo-comprobante'
const blank = (): NumeracionTipoComprobantePayload => ({ sucursal_id: 0, tipo_comprobante_id: 0, anio: new Date().getFullYear(), desde: 1, hasta: 999999, actual: 0, activo: true })
const rows = ref<NumeracionTipoComprobante[]>([]), branches = ref<CatalogoNumeracion[]>([]), voucherTypes = ref<CatalogoNumeracion[]>([]), search = ref(''), page = ref(1), lastPage = ref(1), total = ref(0), loading = ref(false), error = ref(''), success = ref(''), showForm = ref(false), editing = ref<number | null>(null)
const form = reactive(blank())
const message = (e: unknown) => e instanceof Error ? e.message : 'No se pudo completar la operación.'
const progress = (x: NumeracionTipoComprobante) => Math.max(0, Math.min(100, Math.round(((x.actual - x.desde + 1) / Math.max(1, x.hasta - x.desde + 1)) * 100)))
async function load(next = 1) { loading.value = true; error.value = ''; try { const r = await listarNumeracionesTipoComprobante(search.value, next); rows.value = r.data; branches.value = r.sucursales || branches.value; voucherTypes.value = r.tipos_comprobante || voucherTypes.value; page.value = r.current_page; lastPage.value = r.last_page; total.value = r.total } catch (e) { error.value = message(e) } finally { loading.value = false } }
function create() { editing.value = null; Object.assign(form, blank()); showForm.value = true }
async function edit(item: NumeracionTipoComprobante) { loading.value = true; try { const x = await obtenerNumeracionTipoComprobante(item.id); editing.value = x.id; Object.assign(form, { sucursal_id: x.sucursal_id, tipo_comprobante_id: x.tipo_comprobante_id, anio: x.anio, desde: x.desde, hasta: x.hasta, actual: x.actual, activo: Boolean(x.activo) }); showForm.value = true } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function save() { if (form.hasta < form.desde) { error.value = 'El campo Hasta no puede ser menor que Desde.'; return } if (form.actual < form.desde - 1 || form.actual > form.hasta) { error.value = 'El número actual debe estar entre Desde - 1 y Hasta.'; return } loading.value = true; error.value = ''; try { await guardarNumeracionTipoComprobante(editing.value, { ...form }); success.value = `Numeración ${editing.value ? 'actualizada' : 'registrada'} correctamente.`; showForm.value = false; await load(page.value) } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function toggle(item: NumeracionTipoComprobante) { const action = item.activo ? 'desactivar' : 'activar'; if (!confirm(`¿Desea ${action} esta numeración?`)) return; loading.value = true; try { await cambiarEstadoNumeracionTipoComprobante(item.id); success.value = `Numeración ${item.activo ? 'desactivada' : 'activada'} correctamente.`; await load(page.value) } catch (e) { error.value = message(e) } finally { loading.value = false } }
function clear() { search.value = ''; load(1) }
onMounted(() => load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Numeración de comprobantes</nav><header class="hero"><div class="mark">NC</div><div><small>MIA · FINANZAS · MAESTROS</small><h1>Numeración de comprobantes</h1><p>Rangos de correlativos por sucursal, ejercicio y tipo de comprobante.</p></div><strong>{{total}} configuraciones</strong><button @click="create">+ Nueva numeración</button></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><form class="filters" @submit.prevent="load(1)"><input v-model.trim="search" placeholder="Buscar año, sucursal o tipo de comprobante"><button>Buscar</button><button type="button" class="soft" @click="clear">Limpiar</button></form><section class="card"><div v-if="loading" class="empty">Procesando…</div><div v-else-if="!rows.length" class="empty">No se encontraron numeraciones.</div><div v-else class="scroll"><table><thead><tr><th>Año</th><th>Sucursal</th><th>Tipo de comprobante</th><th>Rango</th><th>Actual</th><th>Uso</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><b>{{item.anio}}</b></td><td>{{item.sucursal?.nombre}}</td><td>{{item.tipo_comprobante?.detalle}}</td><td>{{item.desde.toLocaleString()}} — {{item.hasta.toLocaleString()}}</td><td><b>{{item.actual.toLocaleString()}}</b></td><td><div class="progress"><i :style="{width:`${progress(item)}%`}"></i></div><small>{{progress(item)}}%</small></td><td><span :class="item.activo?'good':'bad'">{{item.activo?'ACTIVA':'INACTIVA'}}</span></td><td class="actions"><button class="edit" @click="edit(item)">Editar</button><button :class="item.activo?'danger':'activate'" @click="toggle(item)">{{item.activo?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1" class="pager"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="showForm" class="backdrop" @mousedown.self="showForm=false"><form class="dialog" @submit.prevent="save"><header><div><small>{{editing?'EDICIÓN':'NUEVO REGISTRO'}}</small><h2>{{editing?'Editar':'Registrar'}} numeración</h2></div><button type="button" @click="showForm=false">×</button></header><div class="twocol"><label>Sucursal<select v-model.number="form.sucursal_id" required><option :value="0" disabled>Seleccione</option><option v-for="x in branches" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Tipo de comprobante<select v-model.number="form.tipo_comprobante_id" required><option :value="0" disabled>Seleccione</option><option v-for="x in voucherTypes" :key="x.id" :value="x.id">{{x.detalle}}</option></select></label></div><div class="threecol"><label>Año<input v-model.number="form.anio" type="number" min="2000" max="9999" required></label><label>Desde<input v-model.number="form.desde" type="number" min="1" required></label><label>Hasta<input v-model.number="form.hasta" type="number" min="1" required></label></div><label>Número actual<input v-model.number="form.actual" type="number" :min="form.desde-1" :max="form.hasta" required></label><label class="check"><input v-model="form.activo" type="checkbox"> Numeración activa</label><footer><button type="button" class="soft" @click="showForm=false">Cancelar</button><button :disabled="loading">Guardar</button></footer></form></div></div></template>
<style scoped>
.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;color:#91a0a5;font-size:.68rem}nav a{color:var(--a)}.hero{display:flex;align-items:center;gap:14px;padding:20px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero>div:nth-child(2){flex:1}.hero small,.dialog small{color:var(--a);font-size:.49rem;font-weight:800}.hero h1{margin:3px 0;font-size:1.3rem}.hero p{margin:0;color:#7c8b91;font-size:.65rem}.hero strong{font-size:.55rem}button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;cursor:pointer}.soft{color:#607078;background:#edf2f3}.flash{padding:10px;border-radius:6px;font-size:.55rem}.badmsg{color:#9b3d48;background:#fdebee}.okmsg{color:#236c50;background:#e8f7ee}.filters{margin-top:11px;padding:13px;display:grid;grid-template-columns:1fr auto auto;gap:7px;background:#fff}.filters input,.dialog input,.dialog select{box-sizing:border-box;width:100%;padding:9px;border:1px solid #d5dfe2;border-radius:6px;background:#fff;font-size:.5rem}.card{margin-top:11px;background:#fff}.scroll{overflow:auto}table{width:100%;min-width:1000px;border-collapse:collapse;font-size:.49rem}th,td{padding:10px;border-bottom:1px solid #e3e9eb;text-align:left}th{color:#fff;background:#435d6c}td small{font-size:.43rem}.progress{width:90px;height:5px;border-radius:4px;background:#e4eaec;overflow:hidden}.progress i{display:block;height:100%;background:var(--a)}.good,.bad{padding:4px 8px;border-radius:10px;font-size:.42rem;font-weight:800}.good{color:#267153;background:#e5f7ec}.bad{color:#9d414a;background:#fdebed}.actions{display:flex;gap:5px}.edit{background:#c98a24}.danger{background:#b74b54}.activate{background:#27875f}.empty{padding:50px;text-align:center}.pager{padding:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.5rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(680px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog>header div{flex:1}.dialog h2{margin:3px 0 15px}.dialog>header button{color:#66757b;background:none;font-size:1.2rem}.dialog label{display:grid;gap:5px;margin:10px 0;font-size:.52rem;font-weight:700}.twocol,.threecol{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.threecol{grid-template-columns:repeat(3,1fr)}.dialog .check{display:flex;align-items:center}.dialog .check input{width:auto}.dialog footer{display:flex;justify-content:center;gap:8px;margin-top:15px}@media(max-width:650px){.filters,.twocol,.threecol{grid-template-columns:1fr}.hero{flex-wrap:wrap}.mark{display:none}}
</style>
